const input = $input.all();
const seen = new Set();
return input.map((item) => {
  const raw = item.json;
  const text = (value) => String(value ?? '').trim();
  const email = text(raw.email).toLowerCase();
  const phone = text(raw.phone).replace(/\D/g, '');
  const service = text(raw.service).toLowerCase();
  const eventId = text(raw.event_id);
  const contactKey = email || phone || 'no-contact';
  const duplicateKey = `${contactKey}|${service || 'no-service'}`;
  const errors = [];
  if (!eventId) errors.push('event_id_required');
  if (!email && !phone) errors.push('email_or_phone_required');
  if (!service) errors.push('service_required');
  if (!Boolean(raw.consent_to_contact)) errors.push('contact_consent_required');
  let outcome;
  if (errors.length) outcome = 'invalid';
  else if (seen.has(duplicateKey)) outcome = 'duplicate';
  else {
    seen.add(duplicateKey);
    if (Boolean(raw.human_review_required)) outcome = 'human_review';
    else if (Boolean(raw.simulate_adapter_failure)) outcome = 'integration_exception';
    else outcome = 'accepted';
  }
  return {
    json: {
      ...raw,
      email,
      phone,
      service,
      correlation_id: eventId.toLowerCase().replaceAll('_', '-'),
      duplicate_key: duplicateKey,
      outcome,
      errors,
      is_invalid: outcome === 'invalid',
      is_duplicate: outcome === 'duplicate',
      needs_human_review: outcome === 'human_review',
      has_integration_exception: outcome === 'integration_exception',
      external_actions_performed: false
    }
  };
});
